const claudeResponse = $('Call Claude').first().json;
const body = claudeResponse.body || claudeResponse;
const text = body.content?.[0]?.text || 'I was unable to generate a response. Please try again.';

// Parse for any structured actions in the response
let suggestedActions = [];
try {
  const actionMatches = text.match(/\{[^}]*"action"[^}]*\}/g);
  if (actionMatches) {
    suggestedActions = actionMatches.map(m => {
      try { return JSON.parse(m); } catch { return null; }
    }).filter(Boolean).map(a => ({
      type: a.action,
      params: a.params || {},
      label: a.description || a.action
    }));
  }
} catch (e) { /* no actions found, that's fine */ }

return [{
  json: {
    success: true,
    message: text,
    suggestedActions,
    structuredData: null
  }
}];
